const config = {
  "previewFeatures": [],
  "clientVersion": "7.10.1",
  "engineVersion": "d1b3f377ca835d73fd50954a5e22128b9ebdd6b8",
  "activeProvider": "postgresql",
  "inlineSchema": "datasource db {\n  provider = \"postgresql\"\n}\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../lib/generated/client\"\n}\n\n// ----------------------------------------------------\n// 1. MULTI-BRANCH SYSTEM (منظومة الفروع المتعددة)\n// ----------------------------------------------------\nmodel Branch {\n  id              String   @id @default(cuid())\n  name            String // e.g. \"فرع عباس العقاد الرئيسي\", \"فرع أول عباس - كشري التحرير\"\n  code            String   @unique // \"BR-ABBAS-MAIN\", \"BR-TAHRIR\"\n  address         String\n  phone           String\n  whatsapp        String?\n  googleMapsUrl   String?\n  isActive        Boolean  @default(true)\n  isDayOffEnabled Boolean  @default(false)\n  weeklyDayOff    String   @default(\"NONE\") // NONE, MONDAY, etc.\n  dayOffMessage   String?\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n\n  users        User[]\n  branchStocks BranchStock[]\n  invoices     Invoice[]\n  expenses     Expense[]\n  shifts       Shift[]\n  offers       Offer[]\n  customers    Customer[]\n}\n\n// ----------------------------------------------------\n// 2. USERS & RBAC (طاقم العمل والمستخدمين والصلاحيات)\n// ----------------------------------------------------\nmodel User {\n  id        String   @id @default(cuid())\n  username  String   @unique\n  password  String\n  pin       String   @default(\"157230\") // PIN سريع للكاشير\n  name      String\n  role      String // \"owner\" | \"general_manager\" | \"branch_manager\" | \"cashier\" | \"storekeeper\"\n  branchId  String?\n  branch    Branch?  @relation(fields: [branchId], references: [id], onDelete: SetNull)\n  phone     String?\n  isActive  Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  invoicesHandled Invoice[]\n  shiftsOpened    Shift[]   @relation(\"ShiftsOpened\")\n  shiftsClosed    Shift[]   @relation(\"ShiftsClosed\")\n}\n\n// ----------------------------------------------------\n// 3. CLOTHING INVENTORY: CATEGORIES, PRODUCTS, VARIANTS\n// ----------------------------------------------------\nmodel Category {\n  id        String   @id @default(cuid())\n  nameAr    String   @unique // \"تيشرتات أوفر سايز\", \"بناطيل جينز\", إلخ\n  nameEn    String?\n  slug      String   @unique\n  icon      String? // Emoji or Lucide icon name\n  image     String?\n  sortOrder Int      @default(0)\n  isActive  Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  products Product[]\n}\n\nmodel Product {\n  id            String    @id @default(cuid())\n  nameAr        String\n  nameEn        String?\n  sku           String?   @unique // e.g. \"BAZ-TSH-001\"\n  description   String?\n  categoryId    String?\n  category      Category? @relation(fields: [categoryId], references: [id], onDelete: SetNull)\n  basePrice     Float // سعر البيع الافتراضي\n  costPrice     Float     @default(0.0) // سعر التكلفة\n  discountPrice Float? // سعر الخصم إن وجد\n  featuredImage String?\n  images        String    @default(\"[]\") // JSON array of image URLs\n  material      String? // قطن 100%، ميلتون معالج، جينز تركي، إلخ\n  brand         String    @default(\"BAZAAR\")\n  isFeatured    Boolean   @default(false)\n  isActive      Boolean   @default(true)\n  createdAt     DateTime  @default(now())\n  updatedAt     DateTime  @updatedAt\n\n  variants ProductVariant[]\n}\n\nmodel ProductVariant {\n  id                String   @id @default(cuid())\n  productId         String\n  product           Product  @relation(fields: [productId], references: [id], onDelete: Cascade)\n  color             String // e.g. \"أسود\", \"أبيض\", \"كحلي\", \"بيج\", \"زيتي\"\n  colorHex          String? // \"#000000\", \"#FFFFFF\", etc.\n  image             String? // صورة القطعة بهذا اللون والموديل\n  size              String // \"S\", \"M\", \"L\", \"XL\", \"2XL\", \"3XL\", \"4XL\"\n  barcode           String   @unique // Unique Barcode string e.g. \"6221001001\"\n  sku               String? // e.g. \"BAZ-TSH-001-BLK-XL\"\n  priceOverride     Float? // If this variant has a different price\n  costPriceOverride Float?\n  stockCentral      Int      @default(0) // الرصيد بالمخزن المركزي الرئيسي المشترك\n  createdAt         DateTime @default(now())\n  updatedAt         DateTime @updatedAt\n\n  branchStocks  BranchStock[]\n  invoiceLines  InvoiceLine[]\n  transferLines StockTransferLine[]\n\n  @@unique([productId, color, size])\n}\n\n// ----------------------------------------------------\n// 4. BRANCH ALLOCATION & STOCK TRANSFERS\n// ----------------------------------------------------\nmodel BranchStock {\n  id               String         @id @default(cuid())\n  variantId        String\n  variant          ProductVariant @relation(fields: [variantId], references: [id], onDelete: Cascade)\n  branchId         String\n  branch           Branch         @relation(fields: [branchId], references: [id], onDelete: Cascade)\n  quantity         Int            @default(0) // الرصيد المعروض بصالة بيع الفرع\n  alertLowQuantity Int            @default(2) // تنبيه عند وصول الرصيد لقطعتين\n  createdAt        DateTime       @default(now())\n  updatedAt        DateTime       @updatedAt\n\n  @@unique([variantId, branchId])\n}\n\nmodel StockTransfer {\n  id             String   @id @default(cuid())\n  transferNumber String   @unique // \"TRF-2026-001\"\n  fromLocation   String // \"CENTRAL_WAREHOUSE\" or Branch ID\n  toLocation     String // Branch ID\n  status         String   @default(\"PENDING\") // \"PENDING\" | \"COMPLETED\" | \"CANCELLED\"\n  requestedBy    String?\n  approvedBy     String?\n  notes          String?\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  lines StockTransferLine[]\n}\n\nmodel StockTransferLine {\n  id         String         @id @default(cuid())\n  transferId String\n  transfer   StockTransfer  @relation(fields: [transferId], references: [id], onDelete: Cascade)\n  variantId  String\n  variant    ProductVariant @relation(fields: [variantId], references: [id], onDelete: Restrict)\n  quantity   Int\n  notes      String?\n}\n\n// ----------------------------------------------------\n// 5. CUSTOMERS & LOYALTY CRM (العملاء ونقاط الولاء)\n// ----------------------------------------------------\nmodel Customer {\n  id            String   @id @default(cuid())\n  name          String\n  phone         String   @unique\n  email         String?\n  address       String?\n  governorate   String?  @default(\"القاهرة\")\n  loyaltyPoints Int      @default(0)\n  totalSpent    Float    @default(0.0)\n  totalVisits   Int      @default(0)\n  vipLevel      String   @default(\"REGULAR\") // \"REGULAR\" | \"SILVER\" | \"GOLD\" | \"ROYAL_VIP\"\n  branchId      String?\n  branch        Branch?  @relation(fields: [branchId], references: [id], onDelete: SetNull)\n  notes         String?\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  invoices Invoice[]\n}\n\n// ----------------------------------------------------\n// 6. INVOICES & POS SALES (فواتير المبيعات ونقطة البيع)\n// ----------------------------------------------------\nmodel Invoice {\n  id              String    @id @default(cuid())\n  invoiceNumber   String    @unique // \"BAZ-1001\"\n  branchId        String\n  branch          Branch    @relation(fields: [branchId], references: [id], onDelete: Restrict)\n  cashierId       String?\n  cashierUser     User?     @relation(fields: [cashierId], references: [id], onDelete: SetNull)\n  customerId      String?\n  customer        Customer? @relation(fields: [customerId], references: [id], onDelete: SetNull)\n  customerName    String?\n  customerPhone   String?\n  orderType       String    @default(\"IN_STORE_POS\") // \"IN_STORE_POS\" | \"ONLINE_ORDER\" | \"WHATSAPP_ORDER\"\n  subTotal        Float\n  discountAmount  Float     @default(0.0)\n  taxAmount       Float     @default(0.0)\n  finalTotal      Float\n  paidAmount      Float\n  remainingAmount Float     @default(0.0)\n  paymentMethod   String    @default(\"CASH\") // \"CASH\" | \"VISA\" | \"INSTAPAY\" | \"VODAFONE_CASH\" | \"SPLIT\"\n  splitDetails    String? // JSON if split\n  status          String    @default(\"PAID\") // \"PAID\" | \"PENDING_DELIVERY\" | \"RETURNED\" | \"EXCHANGED\" | \"CANCELLED\"\n  notes           String?\n  shiftId         String?\n  shift           Shift?    @relation(fields: [shiftId], references: [id], onDelete: SetNull)\n  createdAt       DateTime  @default(now())\n  updatedAt       DateTime  @updatedAt\n\n  lines InvoiceLine[]\n}\n\nmodel InvoiceLine {\n  id             String         @id @default(cuid())\n  invoiceId      String\n  invoice        Invoice        @relation(fields: [invoiceId], references: [id], onDelete: Cascade)\n  variantId      String\n  variant        ProductVariant @relation(fields: [variantId], references: [id], onDelete: Restrict)\n  productName    String\n  color          String\n  size           String\n  barcode        String\n  quantity       Int\n  unitPrice      Float\n  costPrice      Float          @default(0.0)\n  discountAmount Float          @default(0.0)\n  total          Float\n}\n\n// ----------------------------------------------------\n// 7. DAILY SHIFTS (الورديات وإقفال الكاشير)\n// ----------------------------------------------------\nmodel Shift {\n  id             String    @id @default(cuid())\n  shiftNumber    String    @unique // \"SH-ABBAS-20261113-001\"\n  branchId       String\n  branch         Branch    @relation(fields: [branchId], references: [id], onDelete: Cascade)\n  openedById     String\n  openedByUser   User      @relation(\"ShiftsOpened\", fields: [openedById], references: [id])\n  closedById     String?\n  closedByUser   User?     @relation(\"ShiftsClosed\", fields: [closedById], references: [id])\n  startTime      DateTime  @default(now())\n  endTime        DateTime?\n  status         String    @default(\"OPEN\") // \"OPEN\" | \"CLOSED\"\n  openingCash    Float     @default(0.0)\n  expectedCash   Float     @default(0.0)\n  actualCash     Float     @default(0.0)\n  cashDifference Float     @default(0.0)\n  totalSales     Float     @default(0.0)\n  cashSales      Float     @default(0.0)\n  visaSales      Float     @default(0.0)\n  instapaySales  Float     @default(0.0)\n  vodafoneSales  Float     @default(0.0)\n  totalReturns   Float     @default(0.0)\n  expensesAmount Float     @default(0.0)\n  handedTo       String?\n  notes          String?\n  createdAt      DateTime  @default(now())\n\n  invoices Invoice[]\n  expenses Expense[]\n}\n\n// ----------------------------------------------------\n// 8. EXPENSES (المصروفات النثرية والتشغيلية)\n// ----------------------------------------------------\nmodel Expense {\n  id            String   @id @default(cuid())\n  branchId      String\n  branch        Branch   @relation(fields: [branchId], references: [id], onDelete: Cascade)\n  title         String // e.g. \"ضيافة عملاء\", \"أكياس مطبوعة\", \"فواتير كهرباء\"\n  amount        Float\n  category      String   @default(\"MISC\") // \"RENT\" | \"UTILITIES\" | \"SUPPLIES\" | \"SALARIES\" | \"HOSPITALITY\" | \"MARKETING\" | \"MISC\"\n  paymentMethod String   @default(\"CASH\")\n  recordedBy    String?\n  notes         String?\n  shiftId       String?\n  shift         Shift?   @relation(fields: [shiftId], references: [id], onDelete: SetNull)\n  createdAt     DateTime @default(now())\n}\n\n// ----------------------------------------------------\n// 9. LIVE CHAT & COMMUNICATIONS (المحادثات المباشرة)\n// ----------------------------------------------------\nmodel ChatMessage {\n  id             String   @id @default(cuid())\n  conversationId String // customer phone or id\n  branchId       String?\n  customerPhone  String\n  customerName   String\n  sender         String // \"CUSTOMER\" | \"STORE\" | \"ADMIN\"\n  senderName     String\n  message        String\n  isRead         Boolean  @default(false)\n  createdAt      DateTime @default(now())\n}\n\n// ----------------------------------------------------\n// 10. WEB PUSH NOTIFICATIONS (إشعارات الهواتف)\n// ----------------------------------------------------\nmodel PushSubscription {\n  id            String   @id @default(cuid())\n  endpoint      String   @unique\n  p256dh        String\n  auth          String\n  userRole      String   @default(\"CUSTOMER\") // \"CUSTOMER\" | \"ADMIN\" | \"CASHIER\"\n  branchId      String?\n  customerPhone String?\n  userName      String?\n  createdAt     DateTime @default(now())\n}\n\n// ----------------------------------------------------\n// 11. OFFERS & PROMOTIONS (العروض الحصرية لكل فرع)\n// ----------------------------------------------------\nmodel Offer {\n  id               String    @id @default(cuid())\n  titleAr          String\n  badge            String? // e.g. \"خصم 30% 🔥\"\n  price            Float\n  oldPrice         Float?\n  discountPercent  Int?\n  image            String?\n  description      String?\n  features         String    @default(\"[]\") // JSON array of features\n  branchId         String?\n  branch           Branch?   @relation(fields: [branchId], references: [id], onDelete: SetNull)\n  announcementText String? // نص الإشعار الترويجي الذي يصل لهواتف العملاء\n  broadcastSentAt  DateTime?\n  isActive         Boolean   @default(true)\n  sortOrder        Int       @default(0)\n  createdAt        DateTime  @default(now())\n  updatedAt        DateTime  @updatedAt\n}\n\n// ----------------------------------------------------\n// 12. SYSTEM SETTINGS & MASTER EMERGENCY LOCK\n// ----------------------------------------------------\nmodel SystemSettings {\n  id                Int    @id @default(1)\n  brandNameAr       String @default(\"بزار كاجوال وير\")\n  brandNameEn       String @default(\"BAZAAR Casual Wear\")\n  logoUrl           String @default(\"/logo.jpg\")\n  hotline           String @default(\"01008038041\")\n  whatsappNumber    String @default(\"01008038041\")\n  facebookUrl       String @default(\"https://www.facebook.com/share/1Dq8mYkoij/\")\n  facebookUrl2      String @default(\"https://www.facebook.com/profile.php?id=100090095202108&mibextid=wwXIfr\")\n  tiktokUrl         String @default(\"https://www.tiktok.com/@mohamed_ashraf327?_r=1&_t=ZS-9BMGDqeFbr2\")\n  instagramUrl      String @default(\"https://www.instagram.com/bazaar_casual_wear\")\n  receiptFooterText String @default(\"شكراً لزيارتكم بزار كاجوال وير • الاستبدال والاسترجاع خلال 14 يوماً بأصل الفاتورة والباركود\")\n\n  // Hero Section Dynamic Customization (صورة الهيدر والبانر الشبابي الديناميكي)\n  heroBannerImage String @default(\"https://images.unsplash.com/photo-1516257984-b1b4d707412e?auto=format&fit=crop&w=1000&q=80\")\n  heroTagline     String @default(\"طقم الأوفر سايز والكارجو التكتيكال\")\n  heroDescription String @default(\"قطن مصري 100% هيفي ويت معالج ضد الانكماش مع نسيج كارجو ووتر بروف\")\n\n  // Emergency Master Lockout (زر الطوارئ الحصري للمالك Maestro لتعطيل الحسابات وضمان الملكية)\n  isMasterLocked    Boolean @default(false)\n  masterLockMessage String  @default(\"النظام في وضع الصيانة والتحديث الإداري العام. يرجى التواصل مع إدارة بزار كاجوال وير.\")\n\n  // AI Gemini & Integration Keys\n  geminiApiKey           String?\n  loyaltyPointsPer100Egp Int      @default(5)\n  currency               String   @default(\"ج.م\")\n  createdAt              DateTime @default(now())\n  updatedAt              DateTime @updatedAt\n}\n"
}

